CompanyReferenceManagement = {
    init: async function (app, container, company) {
        app = app || session.app;
        container = container || $(".component[name=CompanyReferenceManagement]]");
        if(company) { await CompanyReferenceManagement.initWidget(container, company); }
    },

    initWidget: async function(container, company) {
        var config = {
            endpoint: "B2B/CompanyReference",
            odataAppend: "?$filter=CompanyId eq " + company.Id,
            onChange: function (e) {
                company.References = this.data();
                for (var i in company.References) {
                    company.References[i].Id = company.References[i].SystemId + "|" + company.References[i].Value;
                    delete company.References[i].type;
                }
            }
        };
        var ds = await model.getDatasource(config);

        var systems = await model.getDatasource({ endpoint: "B2B/System" });
        var referenceGrid = new GridWidget(container, ds);
        referenceGrid.toolbar = "<button name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[newreference]]</button>";
        referenceGrid.groupable = false;
        referenceGrid.editable = false;
        referenceGrid.pageable = false;
        referenceGrid.columns =
        [
            {
                field: "SystemId",
                title: "[resource_shortdisplayname[system]]",
                description: "[resource_description[system]]",
                editor: function (cell, options) {
                    $('<input data-text-field="Name" data-value-field="Id" data-bind="value:' + options.field + '"/>')
                        .appendTo(cell)
                        .kendoDropDownList({ dataSource: systems, dataTextField: "Name", dataValueField: "Id" });
                }
            },
            { field: "Value", title: "[resource_shortdisplayname[value]]", description: "[resource_description[value]]" }
        ];
        referenceGrid.commands.push({ name: "delete", icon: "k-i-delete", text: "[resource_displayname[delete]]" });
        referenceGrid.dataBound = function () {
            $("a[name=delete]", referenceGrid.gridElement).on("click", (e) => CompanyReferenceManagement.destroy(e, referenceGrid));
        };
        await referenceGrid.init();
        $("button[name=create]", referenceGrid.gridElement).off().on("click", (e) => CompanyReferenceManagement.create(company, referenceGrid));
    },

    create: async function(company, grid, systems) {
        var model = kendo.observable({ CompanyId: company.Id, SystemId: "", Value:  "" });
        var refDialog = new Dialog({title: "[resource_displayname[addreference]]", width: 800, height: 250});
        refDialog.template = $("[name=addreferencedialog]").html();
        refDialog.events.add = async function() {
            var companyRef = model.toJSON();
            companyRef.Id = companyRef.SystemId + "|" + companyRef.Value;
            await api.post("B2B/CompanyReference", companyRef).then(() => {
                notification.success("[resource_displayname[added]]");
                grid.refresh();
                refDialog.events.close();
            }).catch((err) => error(err));
        };
        refDialog.init(() => {
            $("[name=systemId]").kendoDropDownList({
                dataTextField: "Id",
                dataValueField: "Id",
                optionLabel: "[resource_displayname[select]]",
                dataSource: systems
            });
            kendo.bind(refDialog.element, newRef);
        });
    },

    destroy: async function(e, grid) {
        e.preventDefault();
        var reference = grid.dataItem($(e.currentTarget).closest("tr"));
        await api.destroy("B2B/CompanyReference('" + reference.Id + "')").then(() => {
            grid.refresh();
        }).catch((err) => error(err));
    }
}
